<?php require_once __DIR__.'/attendance.php';
function qv($sql,$p=[]){global $pdo;$s=$pdo->prepare($sql);$s->execute($p);return (int)$s->fetchColumn();}
function bars(array $rows,string $l,string $v){echo hbars($rows,$l,$v);}
function emp_dash(){global $pdo;$id=(int)$_SESSION['eid'];
 $a=$pdo->prepare('SELECT * FROM attendance WHERE employee_id=? AND work_date=CURDATE()');$a->execute([$id]);$a=$a->fetch();
 $b=$pdo->prepare('SELECT b.*,t.name FROM leave_balances b JOIN leave_types t ON t.id=b.leave_type_id WHERE b.employee_id=? AND b.year=YEAR(CURDATE()) AND t.is_active=1');$b->execute([$id]);
 $r=$pdo->prepare('SELECT r.*,t.name tn FROM leave_requests r JOIN leave_types t ON t.id=r.leave_type_id WHERE r.employee_id=? ORDER BY r.id DESC LIMIT 5');$r->execute([$id]);
 page_start('لوحة التحكم');
 $nm=$pdo->prepare('SELECT full_name FROM employees WHERE id=?');$nm->execute([$id]);$ms=$pdo->prepare("SELECT status,COUNT(*) FROM attendance WHERE employee_id=? AND work_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01') GROUP BY status");$ms->execute([$id]);$ms=$ms->fetchAll(PDO::FETCH_KEY_PAIR);
 $tone=!$a?'':($a['status']==='late'?'warn':'ok');$stx=!$a?'لم يُسجَّل حضورك بعد':SA[$a['status']];
 $h2=!$a?'لم تسجّل حضورك اليوم':(!$a['check_out']?'سجّلت حضورك الساعة '.substr((string)$a['check_in'],0,5):'اكتمل يوم عملك');
 $sub=!$a?'امسح رمز QR أو افتحه من ملفك لتسجيل الحضور.':(!$a['check_out']?'لا تنسَ تسجيل الانصراف عند المغادرة.':'تم تسجيل الانصراف الساعة '.substr((string)$a['check_out'],0,5).'.');?>
<div class="hello"><h1>مرحبًا، <?=e($nm->fetchColumn())?></h1><span><?=e(ar_date(time()))?></span></div>
<section class="today" aria-label="حضور اليوم"><div class="today-main"><div><span class="st <?=$tone?>"><?=e($stx)?></span><h2><?=e($h2)?></h2><p><?=e($sub)?></p></div>
<div class="row"><a class="btn" href="attendance/scan.php"><?=ic('scan')?>تسجيل الحضور</a><a class="btn ghost" href="employees/view.php#qr-card"><?=ic('qr')?>عرض رمزي</a></div></div>
<div class="today-side"><div><span>الدخول</span><b><?=e($a['check_in']??'—')?></b></div><div><span>الانصراف</span><b><?=e($a['check_out']??'—')?></b></div><div><span>ساعات العمل</span><b><?=hm($a['work_minutes']??0)?></b></div><div><span>التأخير (د)</span><b><?=(int)($a['late_minutes']??0)?></b></div><div><span>إضافي (د)</span><b><?=(int)($a['overtime_minutes']??0)?></b></div><div><span>الحالة</span><b style="font-size:1.05rem"><?=e($stx)?></b></div></div></section>
<?=kpis([[(int)(($ms['present']??0)+($ms['late']??0)),'أيام حضور هذا الشهر','ok','','check-circle'],[(int)($ms['late']??0),'تأخير','warn','','clock'],[(int)($ms['absent']??0),'غياب','err','','x-circle'],[(int)($ms['on_leave']??0),'إجازة','info','','sun']])?>
<div class="card-h"><div><h3>أرصدة الإجازات</h3></div><div class="row"><a class="btn sm gold" href="employee/leaves.php?new=1"><?=ic('plus')?>طلب إجازة</a></div></div>
<div class="bal-grid"><?php $nb=0;foreach($b as $x):$nb++;$rem=$x['total_days']-$x['used_days'];?><div class="bal"><div class="t"><?=e($x['name'])?></div><div class="v"><b><?=$rem+0?></b><span>يوم متبقٍ</span></div><div class="prog gold" role="progressbar" aria-valuenow="<?=$x['used_days']+0?>" aria-valuemax="<?=$x['total_days']+0?>"><i style="width:<?=$x['total_days']>0?min(100,round($x['used_days']/$x['total_days']*100)):0?>%"></i></div><div class="f"><span>مستخدم <?=$x['used_days']+0?></span><span>من <?=$x['total_days']+0?></span></div></div><?php endforeach;if(!$nb)echo '<div class="card">'.empty_state('لا توجد أرصدة لهذه السنة','سيُنشئها النظام تلقائيًا عند أول طلب إجازة.','','scale').'</div>';?></div>
<div class="card tbl"><?=card_h('آخر طلبات الإجازة','','<a class="btn sm ghost" href="employee/leaves.php">كل طلباتي</a>')?><table><tr><th>النوع</th><th>من</th><th>إلى</th><th>الأيام</th><th>الحالة</th></tr><?php foreach($r as $x):?><tr><td class="cmain"><?=e($x['tn'])?></td><td><?=e($x['start_date'])?></td><td><?=e($x['end_date'])?></td><td><?=$x['days']+0?></td><td><?=sb($x['status'],LS[$x['status']])?></td></tr><?php endforeach;if(!$r->rowCount())echo empty_row(5,'لا توجد طلبات بعد','عند تقديم طلب إجازة سيظهر هنا مع حالته.','sun');?></table></div><?php page_end();}
function mgr_dash(){global $pdo;$m=(int)$_SESSION['eid'];$T="e.manager_id=$m AND e.status<>'inactive'";
 $tot=qv("SELECT COUNT(*) FROM employees e WHERE $T");$pr=qv("SELECT COUNT(*) FROM attendance a JOIN employees e ON e.id=a.employee_id WHERE $T AND a.work_date=CURDATE() AND a.status IN('present','late','half_day')");
 $lt=qv("SELECT COUNT(*) FROM attendance a JOIN employees e ON e.id=a.employee_id WHERE $T AND a.work_date=CURDATE() AND a.status='late'");
 $lv=qv("SELECT COUNT(DISTINCT e.id) FROM leave_requests r JOIN employees e ON e.id=r.employee_id WHERE $T AND r.status='approved' AND CURDATE() BETWEEN r.start_date AND r.end_date");
 $pe=qv("SELECT COUNT(*) FROM leave_requests r JOIN employees e ON e.id=r.employee_id WHERE $T AND r.status='pending'");
 $team=$pdo->query("SELECT e.full_name,e.photo,a.status,a.check_in,a.check_out FROM employees e LEFT JOIN attendance a ON a.employee_id=e.id AND a.work_date=CURDATE() WHERE $T ORDER BY e.full_name")->fetchAll();
 $pend=$pdo->query("SELECT r.*,e.full_name,t.name tn FROM leave_requests r JOIN employees e ON e.id=r.employee_id JOIN leave_types t ON t.id=r.leave_type_id WHERE $T AND r.status='pending' ORDER BY r.id DESC LIMIT 5")->fetchAll();
 $up=$pdo->query("SELECT r.*,e.full_name,t.name tn FROM leave_requests r JOIN employees e ON e.id=r.employee_id JOIN leave_types t ON t.id=r.leave_type_id WHERE $T AND r.status='approved' AND r.start_date>CURDATE() ORDER BY r.start_date LIMIT 5")->fetchAll();
 page_start('لوحة المدير');$ab=max(0,$tot-$pr-$lv);?>
<div class="hello"><h1>لوحة المدير</h1><span><?=e(ar_date(time()))?></span></div>
<?=kpis([[$tot,'أعضاء الفريق','','','users'],[$pr,'حاضر اليوم','ok','','check-circle'],[$lt,'متأخر','warn','','clock'],[$ab,'غائب / لم يسجل','err','','x-circle'],[$lv,'في إجازة','info','','sun'],[$pe,'طلبات معلقة','','','inbox','leaves/approvals.php']])?>
<?php if($tot):?><div class="card"><?=card_h('توزيع الفريق اليوم')?><?=day_split([['ok','حاضر في الوقت',max(0,$pr-$lt)],['warn','متأخر',$lt],['info','في إجازة',$lv],['err','غائب / لم يسجل',$ab]])?></div><?php endif;?>
<div class="split"><div class="card tbl"><?=card_h('حضور الفريق اليوم','تفاصيل كل عضو')?><table><tr><th>الموظف</th><th>الحالة</th><th>الدخول</th><th>الانصراف</th></tr><?php foreach($team as $x):?><tr><td class="cwho"><div class="who"><img src="<?=av($x['photo'])?>" alt=""><b><?=e($x['full_name'])?></b></div></td><td><?=$x['status']?sb($x['status'],SA[$x['status']]??$x['status']):sb('inactive','لم يسجل')?></td><td><?=e($x['check_in']?:'—')?></td><td><?=e($x['check_out']?:'—')?></td></tr><?php endforeach;if(!$team)echo empty_row(4,'لا يوجد أعضاء في فريقك','عند ربط موظفين بك كمدير مباشر سيظهرون هنا.','users');?></table></div>
<div class="stack"><div class="card tbl"><?=card_h('طلبات بانتظار موافقتك','','<a class="btn sm ghost" href="leaves/approvals.php">الكل</a>')?><table><?php foreach($pend as $x):?><tr><td class="cmain"><?=e($x['full_name'])?><br><small><?=e($x['tn'])?> · <?=$x['days']+0?> يوم</small></td><td><?=e($x['start_date'])?> ← <?=e($x['end_date'])?></td><td class="act"><a class="btn sm" href="leaves/approvals.php">مراجعة</a></td></tr><?php endforeach;if(!$pend)echo empty_row(3,'لا توجد طلبات معلقة','','check-circle');?></table></div>
<div class="card tbl"><?=card_h('الإجازات القادمة')?><table><?php foreach($up as $x):?><tr><td class="cmain"><?=e($x['full_name'])?><br><small><?=e($x['tn'])?></small></td><td><?=e($x['start_date'])?> ← <?=e($x['end_date'])?></td></tr><?php endforeach;if(!$up)echo empty_row(2,'لا توجد إجازات قادمة','','calendar');?></table></div></div></div>
<?php $ta=$pdo->query("SELECT e.full_name,a.work_date,a.status,a.check_in,a.check_out FROM attendance a JOIN employees e ON e.id=a.employee_id WHERE $T ORDER BY a.work_date DESC,a.check_in DESC LIMIT 8")->fetchAll();?>
<div class="card"><?=card_h('نشاط الفريق الأخير')?><ul class="tl"><?php foreach($ta as $x)echo '<li><span class="tl-t">'.e($x['full_name']).'</span> — '.e($SAx=SA[$x['status']]??$x['status']).'<small>'.e($x['work_date'].' '.($x['check_in']?:'')).'</small></li>';if(!$ta)echo '<li class="empty">لا يوجد نشاط بعد.</li>';?></ul></div>
<?php page_end();}
